public class Main {
    public static void main(String[] args) {
        int total = 15000;
        int bayar = 20000;
        System.out.println("Uang cukup? " + (bayar >= total));
        int stok = 0;
        System.out.println("Stok habis? " + (stok == 0));
        String kode = "HEMAT";
        System.out.println("Promo berlaku? " + kode.equals("HEMAT"));
        System.out.println("Ada kembalian? " + (bayar != total));
    }
}

